S=/tmp/claude-0/-home-user-guidebook/5dbc61f3-e21d-5874-a6a8-3a991f0f402c/scratchpad/critic-t008; cd $S; cp head/data/guidebook.db t2.db; cat > probe4.py <<'PY'
import sys; sys.path.insert(0,'scripts'); import db, sqlite3, os
c=sqlite3.connect(os.environ['GUIDEBOOK_DB_PATH']); 
sess=c.execute("select created_by_session from source_value_extractions where extraction_id=30").fetchone()[0] if 'created_by_session' in [x[1] for x in c.execute('pragma table_info(source_value_extractions)')] else 'session_probe'
print('row30', c.execute("select claimed_value, claim_type, substr(claim_text,1,90), substr(notes,1,60) from source_value_extractions where extraction_id=30").fetchone())
ex=c.execute("select extraction_id, claimed_value, substr(claim_text,1,60) from source_value_extractions where notes like '%[VERBATIM-EXEMPT%' and claim_type='numerical' limit 3").fetchall(); print('exempt sample',ex)
def am(eid,val,dry=True):
    try:
        r=db.amend_extraction(eid,'value_as_written',val,'critic probe',session=sess,dry_run=dry); print('ACCEPTED',eid,repr(val),r.get('changed'))
    except db.Refusal as e: print('REFUSED ',eid,repr(val),str(e)[:110])
    except Exception as e: print('CRASH   ',eid,repr(val),type(e).__name__,str(e)[:160])
am(30,'vijf procent'); am(30,'e'); am(30,'bij'); am(30,'Vijf  PROCENT'); am(30,''); am(30,'50 cm'); am(17,'steeper'); am(80,'viisi prosenttia'); am(80,'viisi')
for e,_,_ in ex: am(e,'e')
am(30,'e',dry=False); am(30,'vijf procent',dry=False); am(30,'NULL',dry=False); am(30,' ',dry=False)
print(c.execute("select value_as_written, substr(notes,-160) from source_value_extractions where extraction_id=30").fetchone())
PY
cd head && GUIDEBOOK_DB_PATH=$S/t2.db python3 $S/probe4.py 2>&1 | cut -c1-330; git status --short | head -3; sha256sum data/guidebook.db | cut -c1-12

